const fs = require('fs');
const path = require('path');

// ============================================================
// generar_459_como_uso_la_app.js
// ============================================================
// Chiqui aprende a explicar COMO SE USA LA APP.
//
// Preguntarle a el donde se hace algo es mas natural que buscar un
// tutorial, y ya esta en todas las pantallas.
//
//   Tú: ¿dónde registro una vacuna?
//   Chiqui: Toca Salud en la barra de abajo, entra a Vacunas y usa
//           + Agregar.
//
//   Tú: quiero editar el perfil de Chiquito
//   Chiqui: Toca las tres líneas de arriba a la derecha, entra a
//           Perfil y cuenta, y ahí abre Datos del perfil.
//
//   Tú: necesito que otra persona cuide a mi mascota
//   Chiqui: En el Perfil hay una tarjeta de Co-tutor. Toca + Generar
//           código y comparte ese código con quien quieras.
//
// Cada respuesta es el CAMINO CONCRETO, no una explicacion general.
// Quien pregunta esto quiere hacer algo ahora.
//
// SON 15 CAMINOS: vacunas, antiparasitarios, perfil, co-tutor,
// observaciones, peso, medicamentos, cuidados, registro diario, dias
// pasados, visitas al vet, link para el veterinario, agregar mascota,
// notificaciones y examenes.
//
// NAVEGACION vs DATOS
// "¿donde registro una vacuna?" pide el camino; "¿que vacunas vienen?"
// pide el dato. Se distinguen por el verbo: donde, como, quiero,
// registro, anoto, edito. Sin verbo de accion, es una pregunta por
// datos.
//
// Y SE ARREGLA UN CONFLICTO: la palabra "salio" estaba en las frases de
// paseos, asi que "le salió una masa" respondia sobre paseos. Ahora
// lleva a Observaciones, que es lo correcto.
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) {
  abortar('no se encontro ' + RUTA + '.');
}

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes('const COMOLO')) {
  abortar('el chat ya explica como usar la app. Parece que este script ya se corrio.');
}
if (!actual.includes('flotante = false')) {
  abortar('falta el script 458. Correlo primero.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

const REQUERIDOS = [
  "'use client'",
  'export default function ChiquiChat',
  'const COMOLO',
  'VERBOS_COMO',
  'entra a **Vacunas** y usa **+ Agregar**',
  'tarjeta de **Co-tutor**',
  'El registro diario es el corazón de la app',
  'flotante = false',
  'const EMERGENCIAS',
  'const ALIMENTOS',
];
for (const r of REQUERIDOS) {
  if (!comp.includes(r)) {
    abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
// "salio" no puede seguir en las frases de paseos.
if (comp.includes("'lo saque', 'salio']")) {
  abortar('la palabra "salio" sigue en paseos: capturaria "le salió una masa".');
}
console.log('  OK  los 15 caminos estan y el conflicto esta resuelto');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('Listo. Chiqui ya explica donde se hace cada cosa.');
